import { describe, expect, it } from 'vitest';
import { isResumable, RunConflictError, RunManager, type RunSnapshot } from './adapter.ts';
import { MemoryRunStore } from './adapter.ts';
import { result, scriptedQuery, text, waitFor, type Script } from './helpers.ts';

const SESSION = 'session-1';

/** A session that answers one turn and then waits for more input. */
const oneTurn: Script = async function* ( ctx ) {
	await ctx.nextInput();
	yield text( 'Done.' );
	yield result( 0.4 );
	await ctx.nextInput();
};

function savedRun( overrides: Partial<RunSnapshot> = {} ): RunSnapshot {
	return {
		id: '11111111-1111-4111-8111-111111111111',
		stageId: 'docs',
		version: '4.17.5',
		prompt: '/wpsp-update-docs 4.17.5',
		status: 'interrupted',
		error: null,
		startedAt: 100,
		endedAt: 100,
		sessionId: SESSION,
		costUsd: 1.25,
		files: [ '/repo/docs-user/a.md' ],
		items: [ { kind: 'text', id: 'old', text: 'Earlier work.', subagent: false } ],
		gates: [],
		resumedFrom: null,
		outcome: null,
		...overrides,
	};
}

describe( 'isResumable', () => {
	it( 'needs an ended run with a session', () => {
		expect( isResumable( { status: 'done', sessionId: 's' } ) ).toBe( true );
		expect( isResumable( { status: 'interrupted', sessionId: 's' } ) ).toBe( true );
		expect( isResumable( { status: 'error', sessionId: 's' } ) ).toBe( true );
		expect( isResumable( { status: 'done', sessionId: null } ) ).toBe( false );
		expect( isResumable( { status: 'running', sessionId: 's' } ) ).toBe( false );
		expect( isResumable( { status: 'awaiting_reply', sessionId: 's' } ) ).toBe( false );
	} );
} );

describe( 'RunManager.resume', () => {
	it( 'continues a saved run’s session, carrying its transcript, files and cost', async () => {
		const store = new MemoryRunStore();
		store.save( savedRun() );

		const scripted = scriptedQuery( oneTurn );
		const manager = new RunManager( '/repo', scripted.queryFn, {}, store );
		const run = manager.resume( savedRun().id, '  Pick up the screenshots.  ' );

		await waitFor( () => run.status === 'awaiting_reply' );

		expect( scripted.calls[ 0 ].options.resume ).toBe( SESSION );

		const snapshot = run.snapshot();

		expect( snapshot ).toMatchObject( {
			stageId: 'docs',
			version: '4.17.5',
			prompt: 'Pick up the screenshots.',
			resumedFrom: savedRun().id,
			sessionId: SESSION,
			files: [ '/repo/docs-user/a.md' ],
		} );
		expect( snapshot.id ).not.toBe( savedRun().id );
		// The earlier cost plus this process's own.
		expect( snapshot.costUsd ).toBeCloseTo( 1.65 );
		expect( snapshot.items.map( ( item ) => item.kind ) ).toEqual( [ 'text', 'system', 'user', 'text', 'result' ] );
		expect( snapshot.items[ 2 ] ).toMatchObject( { kind: 'user', text: 'Pick up the screenshots.' } );

		run.stop();
	} );

	it( 'uses a default message when none is given', async () => {
		let firstInput: string | null = null;
		const store = new MemoryRunStore();
		store.save( savedRun() );

		const manager = new RunManager(
			'/repo',
			scriptedQuery( async function* ( ctx ) {
				firstInput = await ctx.nextInput();
				yield result();
				await ctx.nextInput();
			} ).queryFn,
			{},
			store
		);

		manager.resume( savedRun().id, '   ' );
		await waitFor( () => firstInput !== null );

		expect( firstInput ).toBe( 'Continue where you left off.' );
		manager.latest?.stop();
	} );

	it( 'refuses an unknown run, a run without a session, and a run that is still going', async () => {
		const store = new MemoryRunStore();
		store.save( savedRun( { sessionId: null } ) );

		const manager = new RunManager( '/repo', scriptedQuery( oneTurn ).queryFn, {}, store );

		expect( () => manager.resume( 'nope', '' ) ).toThrow( /No such run/ );
		expect( () => manager.resume( savedRun().id, '' ) ).toThrow( /nothing to resume/ );

		const live = manager.start( 'analyze', '4.17.5', '/wpsp-analyze-release 4.17.5' );

		await waitFor( () => live.status === 'awaiting_reply' );
		expect( () => manager.resume( live.id, '' ) ).toThrow( /still in progress/ );

		live.stop();
	} );

	it( 'refuses to resume while another run is active', async () => {
		const store = new MemoryRunStore();
		store.save( savedRun() );

		const manager = new RunManager( '/repo', scriptedQuery( oneTurn ).queryFn, {}, store );
		const live = manager.start( 'analyze', '4.17.5', '/x' );

		expect( () => manager.resume( savedRun().id, '' ) ).toThrow( RunConflictError );

		live.stop();
	} );

	it( 'can resume the live run once it has ended', async () => {
		const manager = new RunManager( '/repo', scriptedQuery( oneTurn ).queryFn, {}, new MemoryRunStore() );
		const first = manager.start( 'analyze', '4.17.5', '/wpsp-analyze-release 4.17.5' );

		await waitFor( () => first.status === 'awaiting_reply' );
		first.finish();

		const second = manager.resume( first.id, 'One more thing.' );

		expect( second.resumedFrom ).toBe( first.id );
		expect( manager.snapshot( first.id )?.status ).toBe( 'done' );

		second.stop();
	} );
} );

describe( 'RunManager history and saving', () => {
	it( 'saves a run when it starts, as it changes, and when it ends', async () => {
		const store = new MemoryRunStore();
		const manager = new RunManager( '/repo', scriptedQuery( oneTurn ).queryFn, {}, store );
		const run = manager.start( 'prep', '4.17.5', '/wpsp-prep-release 4.17.5' );

		expect( store.saved.get( run.id )?.status ).toBe( 'running' );

		await waitFor( () => store.saved.get( run.id )?.status === 'awaiting_reply' );
		expect( store.saved.get( run.id )?.costUsd ).toBe( 0.4 );

		run.finish();

		// The final save is immediate, not debounced.
		expect( store.saved.get( run.id )?.status ).toBe( 'done' );
	} );

	it( 'lists saved and live runs newest first, filtered by version', async () => {
		const store = new MemoryRunStore();
		store.save( savedRun( { id: '22222222-2222-4222-8222-222222222222', version: '4.17.4', startedAt: 50 } ) );
		store.save( savedRun() );

		const manager = new RunManager( '/repo', scriptedQuery( oneTurn ).queryFn, {}, store );

		expect( manager.list().map( ( run ) => run.version ) ).toEqual( [ '4.17.5', '4.17.4' ] );
		expect( manager.list( '4.17.4' ) ).toHaveLength( 1 );
		expect( manager.list( '4.17.5' )[ 0 ] ).toMatchObject( { stageId: 'docs', resumable: true, status: 'interrupted' } );

		const live = manager.start( 'analyze', '4.17.5', '/x' );

		expect( manager.list( '4.17.5' )[ 0 ] ).toMatchObject( { id: live.id, resumable: false } );
		expect( manager.list( '9.9.9' ) ).toEqual( [] );

		live.stop();
	} );

	it( 'shows the most recent saved run when nothing has run since the server started', () => {
		const store = new MemoryRunStore();
		store.save( savedRun() );

		const manager = new RunManager( '/repo', scriptedQuery( oneTurn ).queryFn, {}, store );

		expect( manager.latest ).toBeNull();
		expect( manager.latestSnapshot()?.id ).toBe( savedRun().id );
		expect( manager.get( savedRun().id ) ).toBeNull();
		expect( manager.snapshot( savedRun().id )?.items ).toHaveLength( 1 );
	} );

	it( 'has no latest run with an empty store', () => {
		expect( new RunManager( '/repo', scriptedQuery( oneTurn ).queryFn ).latestSnapshot() ).toBeNull();
	} );
} );
